/* Presentation, interaction orchestration, and reusable themed components. */
const uid=()=>{if(globalThis.crypto?.randomUUID)return crypto.randomUUID();const a=new Uint32Array(4);if(globalThis.crypto?.getRandomValues)crypto.getRandomValues(a);else for(let i=0;i<4;i++)a[i]=Math.random()*4294967296;return [...a].map(n=>n.toString(16).padStart(8,'0')).join('-')};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(n,c='')=>`<i data-lucide="${esc(n)}" class="${c}" aria-hidden="true"></i>`;
const navs=[['Home','house'],['Calendar','calendar-days'],['Focus','leaf'],['Categories','tags'],['Tasks','list-checks'],['Events','calendar-check'],['Reminders','bell'],['Settings','settings']];
const state={page:Store.data.settings.start||'Home',date:Store.today,miniDate:Store.today,view:'Week',selected:null,filterCategory:'All',filterPriority:'All',filterStatus:'All',filterDate:'All',query:'',focusRunning:false,focusRemaining:Store.data.focus.seconds,focusStarted:0,modal:null,modalReturn:null,drag:null};
const humanDate=(date,long=false)=>new Date(date+'T12:00:00').toLocaleDateString('en-US',long?{weekday:'long',month:'long',day:'numeric'}:{weekday:'short',month:'short',day:'numeric'});
const time=(t)=>{if(!t)return 'Anytime';if(Store.data.settings.time==='24')return t;const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const minutes=t=>{const [h,m]=(t||'09:00').split(':').map(Number);return h*60+m};
const fromMinutes=m=>`${String(Math.floor(Math.max(0,Math.min(1439,m))/60)).padStart(2,'0')}:${String(Math.max(0,Math.min(1439,m))%60).padStart(2,'0')}`;
const category=(name)=>Store.data.categories.find(c=>c.name===name)||{name,icon:'leaf'};
const remindText=m=>m===0?'At time of event':m>=1440?`${m/1440} day before`:m>=60?`${m/60} hour${m>60?'s':''} before`:`${m} minutes before`;
const reminderValues=[0,5,10,15,30,60,120,1440];
const options=(values,current)=>values.map(v=>`<option value="${esc(v)}" ${String(v)===String(current)?'selected':''}>${esc(v)}</option>`).join('');
const blank=()=>({id:null,title:'',date:state.date,time:'',end:'',category:'Personal',priority:'Normal',repeat:'Never',interval:2,reminders:[Store.data.settings.defaultReminder],reminderEnabled:false,synced:false,notes:'',location:'',kind:state.page==='Events'?'event':'task',done:false,completedDates:[]});
const getItem=id=>Store.data.items.find(t=>t.id===id);
function refreshIcons(){lucide.createIcons({attrs:{'stroke-width':1.6}})}
function render(){
 const mainScroll=$('#main').scrollTop,calendarScroll=$('.calendar-wrap')?.scrollTop;
 $('#nav').innerHTML=navs.map(([n,i])=>`<button class="nav-item ${state.page===n?'active':''}" data-page="${n}" title="${n}" ${state.page===n?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('');
 const pages={Home:home,Calendar:calendar,Tasks:tasks,Events:events,Focus:focus,Categories:categories,Reminders:reminders,Settings:settings};
 $('#main').innerHTML=(pages[state.page]||home)();$('#main').scrollTop=mainScroll;if(calendarScroll!==undefined&&$('.calendar-wrap'))$('.calendar-wrap').scrollTop=calendarScroll;renderEditor();refreshIcons();
}
function header(title,subtitle,actions=''){return `<div class="page-header"><div class="greeting"><h2>${title}</h2><p>${subtitle}</p></div><div class="header-actions">${actions||`<button class="icon-btn" data-action="notifications" aria-label="Preview a reminder">${icon('bell')}</button><button class="icon-btn" data-action="new" aria-label="New task (Ctrl+N)">${icon('plus')}</button>`}</div></div>`}
function progressCard(date){const ts=Store.on(date),done=ts.filter(t=>Store.done(t,date)).length;return `<section class="panel ornate today-card"><div class="today-title"><h3>${icon('calendar-days')}${date===Store.today?'Today':humanDate(date)}</h3><div class="today-date">${humanDate(date)}</div></div><div class="progress-line"><div class="progress-track" role="progressbar" aria-label="Daily completion" aria-valuenow="${done}" aria-valuemax="${ts.length||1}"><div class="progress-fill" style="width:${ts.length?done/ts.length*100:0}%"></div></div><span class="progress-label">${done} of ${ts.length} done</span></div></section>`}
function taskRow(t,date=state.date,detailed=false){const done=Store.done(t,date);return `<article class="task-row ${done?'complete':''} ${state.selected===t.id?'selected':''}" data-item="${esc(t.id)}" data-date="${date}" draggable="true" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}"><button class="check ${done?'checked':''}" data-action="complete" data-id="${t.id}" data-date="${date}" role="checkbox" aria-checked="${done}" aria-label="${done?'Uncomplete':'Complete'} ${esc(t.title)}">${done?icon('check'):''}</button><div class="task-title"><strong>${esc(t.title)}</strong>${detailed?`<small>${esc(t.category)} · ${t.date?humanDate(date):'No date'} ${t.repeat!=='Never'?'· '+esc(t.repeat):''}</small>`:''}</div>${icon(category(t.category).icon,'category-icon')}${t.synced?`<span class="sync-tag" title="Google Calendar — simulated">${icon('calendar-check')}</span>`:''}${t.priority!=='Normal'?`<span class="badge ${t.priority==='High'?'high':''}">${esc(t.priority)}</span>`:''}<span class="task-time">${time(t.time)}</span><button class="more" data-action="context" data-id="${t.id}" aria-label="Actions for ${esc(t.title)}">${icon('ellipsis')}</button></article>`}
function empty(text='Nothing here yet. A little room to grow.'){return `<div class="panel empty">${icon('sprout')}${esc(text)}</div>`}
function home(){const list=Store.on(state.date),next=list.filter(t=>!Store.done(t,state.date)&&t.time).sort((a,b)=>a.time.localeCompare(b.time))[0],done=list.filter(t=>Store.done(t,state.date)).length;return header(`Good Morning ${icon('leaf')}`,'“Small steps create a brighter you.”')+progressCard(state.date)+`<div class="task-list">${list.map(t=>taskRow(t)).join('')||empty('No tasks for this day. Plant a new one.')}</div><div class="bottom-widgets">${miniCalendar()}<div class="widget-stack"><div class="panel scenic-card"><p>“A more focused,<br>more intentional you.”</p></div><section class="panel stats-strip"><div class="stat"><strong>${done} / ${list.length}</strong>Completed</div><div class="stat"><strong>${next?esc(next.title):'All clear'}</strong>${next?time(next.time):'Enjoy a little quiet'}</div></section></div></div>`}
function miniCalendar(){const d=new Date(state.miniDate+'T12:00:00'),year=d.getFullYear(),month=d.getMonth(),start=new Date(year,month,1),first=Store.data.settings.week==='Monday'?1:0,offset=(start.getDay()-first+7)%7;start.setDate(1-offset);return `<section class="panel mini-calendar"><div class="mini-head"><span>${icon('leaf')}${d.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</span><div><button data-action="mini-prev" aria-label="Previous month">‹</button><button data-action="mini-next" aria-label="Next month">›</button></div></div><div class="mini-grid">${(first?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat']).map(n=>`<span class="day-label">${n}</span>`).join('')}${Array.from({length:42},(_,i)=>{const x=new Date(start);x.setDate(start.getDate()+i);const date=Store.iso(x);return `<button data-action="select-date" data-date="${date}" class="${date===state.date?'selected':''} ${x.getMonth()!==month?'outside':''}" aria-label="${humanDate(date,true)}">${x.getDate()}</button>`}).join('')}</div></section>`}
function renderEditor(item){const t=item||getItem(state.selected)||blank();const isEdit=!!t.id;$('#detail').innerHTML=`<section class="panel ornate editor"><div class="editor-header"><h3>${icon('leaf')}${isEdit?'Task Details':t.kind==='event'?'New Event':'New Task'}</h3><button class="close-editor icon-btn" data-action="close-editor" aria-label="Close editor">${icon('x')}</button>${isEdit?`<button class="icon-btn" data-action="new" aria-label="New task">${icon('plus')}</button>`:''}</div><form id="task-form" class="${isEdit?'show-options':''}"><input class="form-title" id="task-title" name="title" placeholder="Task title…" aria-label="Task title" value="${esc(t.title)}" required maxlength="160"><div class="field">${icon('calendar-days')}<span>Date</span><input type="date" name="date" aria-label="Date" value="${t.date}"></div><div class="field">${icon('clock-3')}<span>Time</span><input type="time" name="time" aria-label="Time" value="${t.time}"></div><div class="field extra-field">${icon('hourglass')}<span>End time</span><input type="time" name="end" aria-label="End time" value="${t.end}"></div><div class="field">${icon('tags')}<span>Category</span><select name="category" aria-label="Category">${options(Store.data.categories.map(c=>c.name),t.category)}</select></div><div class="field extra-field">${icon('list-checks')}<span>Type</span><select name="kind" aria-label="Item type">${options(['task','event'],t.kind)}</select></div>${isEdit?`<div class="field">${icon('circle-check')}<span>Completed</span><input class="toggle" type="checkbox" name="done" aria-label="Completed" ${Store.done(t,state.date)?'checked':''}></div>`:''}<div class="field">${icon('bell')}<span>Reminder</span><input class="toggle" type="checkbox" name="reminderEnabled" aria-label="Reminder" ${t.reminderEnabled&&t.reminders.length?'checked':''}></div><div class="reminder-options" id="reminder-options" ${t.reminderEnabled?'':'hidden'}>${(t.reminders||[]).map(m=>`<button type="button" class="reminder-chip" data-action="remove-reminder" data-value="${m}" title="Remove reminder">${esc(remindText(m))} ×</button>`).join('')}<select id="reminder-add" aria-label="Add reminder"><option value="">+ Add reminder</option>${reminderValues.map(m=>`<option value="${m}">${remindText(m)}</option>`).join('')}</select></div><div class="field">${icon('calendar-check')}<span>Google Calendar</span><input class="toggle" type="checkbox" name="synced" aria-label="Add to Google Calendar" ${t.synced?'checked':''}></div><div class="field extra-field">${icon('repeat-2')}<span>Repeat</span><select name="repeat" aria-label="Repeat">${options(['Never','Daily','Weekdays','Weekly','Monthly','Yearly','Custom'],t.repeat)}</select></div><div class="field" id="interval-field" ${t.repeat==='Custom'?'':'hidden'}>${icon('repeat')}<span>Every (days)</span><input type="number" name="interval" min="1" max="365" value="${t.interval||2}" aria-label="Repeat interval in days"></div><div class="field extra-field">${icon('flag')}<span>Priority</span><select name="priority" aria-label="Priority">${options(['Low','Normal','High'],t.priority)}</select></div><div class="field extra-field" id="location-field" ${t.kind==='event'?'':'hidden'}>${icon('map-pin')}<span>Location</span><input name="location" aria-label="Location" value="${esc(t.location)}" placeholder="Optional"></div><button type="button" class="advanced-button" data-action="advanced-options" aria-expanded="${isEdit}">${icon('chevron-down')}${isEdit?'Fewer task options':'More task options'}</button><label class="notes-label" for="notes">${icon('notebook-pen')} Notes</label><textarea class="notes" id="notes" name="notes" placeholder="A little detail for later…">${esc(t.notes)}</textarea><button class="primary ornate" type="submit">${isEdit?'Save Changes':'Add '+(t.kind==='event'?'Event':'Task')}</button>${isEdit?`<button class="danger" type="button" data-action="delete" data-id="${t.id}">${icon('trash-2')} Delete ${t.repeat==='Never'?'item':'series'}</button>`:''}<div class="editor-foot">${icon('hard-drive')} Saved on this device · Google sync is simulated</div></form></section><section class="panel focus-widget"><h4>${icon('leaf')} Focus</h4><div class="focus-ring">${icon('sprout')}</div><p>Stay consistent.<br>Progress, not perfection.</p><button class="secondary" data-page="Focus">Start a quiet moment</button></section>`;
 $('#task-form').dataset.reminders=JSON.stringify(t.reminders||[]);refreshIcons();
}
function weekStart(date){const d=new Date(date+'T12:00:00'),first=Store.data.settings.week==='Sunday'?0:1;return Store.shift(date,-((d.getDay()-first+7)%7))}
function calendar(){const start=weekStart(state.date),dates=state.view==='Day'?[state.date]:Array.from({length:7},(_,i)=>Store.shift(start,i));return header('Calendar','A little space for what matters.')+`<div class="toolbar"><button class="icon-btn" data-action="cal-prev" aria-label="Previous period">${icon('chevron-left')}</button><button class="secondary" data-action="cal-today">Today</button><button class="icon-btn" data-action="cal-next" aria-label="Next period">${icon('chevron-right')}</button><span style="flex:1;font:16px Georgia">${new Date(state.date+'T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})}</span><div class="segmented" aria-label="Calendar view">${['Day','Week','Month'].map(v=>`<button data-view="${v}" class="${state.view===v?'active':''}">${v}</button>`).join('')}</div></div>${state.view==='Day'?progressCard(state.date)+`<h4 class="section-label">Anytime Tasks</h4><div class="task-list" style="margin-bottom:15px">${Store.on(state.date).filter(t=>!t.time).map(t=>taskRow(t)).join('')||'<span class="muted" style="font-size:12px">No anytime tasks for this day.</span>'}</div>`:''}${state.view==='Month'?monthCalendar():timeline(dates)}<p class="calendar-note">Click an empty slot to add an event. Drag cards to move them; drag the bottom edge to resize. Repeating items move as a series.</p>`}
function timeline(dates){let html=`<div class="calendar-wrap"><div class="calendar-grid ${dates.length===1?'day':''}"><div class="cal-heading">Time</div>${dates.map(d=>`<div class="cal-heading ${d===Store.today?'is-today':''}">${new Date(d+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'})}<strong>${new Date(d+'T12:00:00').getDate()}</strong></div>`).join('')}`;for(let hour=0;hour<24;hour++){html+=`<div class="time-label">${time(`${String(hour).padStart(2,'0')}:00`)}</div>`;for(const d of dates){const items=Store.on(d).filter(t=>t.time&&Math.floor(minutes(t.time)/60)===hour).sort((a,b)=>minutes(a.time)-minutes(b.time));html+=`<div class="cal-slot" data-slot-date="${d}" data-hour="${hour}" tabindex="0" role="button" aria-label="New event ${humanDate(d)} ${time(fromMinutes(hour*60))}">${items.map((t,idx)=>{const duration=Math.max(30,t.end?minutes(t.end)-minutes(t.time):60),height=duration/60*56-4;return `<div class="calendar-event ${t.kind==='event'?'event-kind':''}" data-item="${t.id}" data-date="${d}" draggable="true" tabindex="0" role="button" aria-label="Edit ${esc(t.title)}" style="top:${(minutes(t.time)%60)/60*56+2}px;height:${height}px;${items.length>1?`left:${3+idx*(95/items.length)}%;width:${90/items.length}%`:''}"><strong>${esc(t.title)}</strong><small>${time(t.time)}${t.end?' – '+time(t.end):''}</small><div class="resize-handle" data-resize="${t.id}" aria-label="Resize ${esc(t.title)}"></div></div>`}).join('')}</div>`}}return html+'</div></div>'}
function monthCalendar(){const d=new Date(state.date+'T12:00:00'),first=Store.iso(new Date(d.getFullYear(),d.getMonth(),1)),start=weekStart(first),labels=Store.data.settings.week==='Monday'?['Mon','Tue','Wed','Thu','Fri','Sat','Sun']:['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];return `<div class="calendar-wrap"><div class="month-grid">${labels.map(x=>`<div class="cal-heading">${x}</div>`).join('')}${Array.from({length:42},(_,i)=>{const date=Store.shift(start,i),x=new Date(date+'T12:00:00'),list=Store.on(date);return `<div class="month-cell ${x.getMonth()!==d.getMonth()?'outside':''} ${date===state.date?'selected':''}" data-month-date="${date}" tabindex="0" role="button" aria-label="${humanDate(date,true)}"><span>${x.getDate()}</span>${list.slice(0,3).map(t=>`<button class="month-event" data-item="${t.id}" data-date="${date}" title="${esc(t.title)}">${esc(t.title)}</button>`).join('')}${list.length>3?`<small style="font-size:10px">+${list.length-3} more</small>`:''}</div>`}).join('')}</div></div>`}
function filterToolbar(){return `<div class="toolbar"><input id="task-query" placeholder="Filter tasks…" aria-label="Filter tasks" value="${esc(state.query)}"><select data-filter="filterCategory" aria-label="Filter category">${options(['All',...Store.data.categories.map(c=>c.name)],state.filterCategory)}</select><select data-filter="filterPriority" aria-label="Filter priority">${options(['All','Low','Normal','High'],state.filterPriority)}</select><select data-filter="filterStatus" aria-label="Filter status">${options(['All','Completed','Incomplete','Synced','Local','Recurring'],state.filterStatus)}</select><select data-filter="filterDate" aria-label="Filter date">${options(['All','Today','Next 7 days','No date'],state.filterDate)}</select></div>`}
function filtered(kind){return Store.data.items.filter(t=>(!kind||t.kind===kind)&&(state.filterCategory==='All'||t.category===state.filterCategory)&&(state.filterPriority==='All'||t.priority===state.filterPriority)&&(state.filterStatus==='All'||state.filterStatus==='Completed'&&Store.done(t,state.date)||state.filterStatus==='Incomplete'&&!Store.done(t,state.date)||state.filterStatus==='Synced'&&t.synced||state.filterStatus==='Local'&&!t.synced||state.filterStatus==='Recurring'&&t.repeat!=='Never')&&(state.filterDate==='All'||state.filterDate==='Today'&&Store.matches(t,Store.today)||state.filterDate==='Next 7 days'&&t.date>=Store.today&&t.date<=Store.shift(Store.today,7)||state.filterDate==='No date'&&!t.date)&&(!state.query||`${t.title} ${t.notes} ${t.category}`.toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>a.order-b.order)}
function tasks(){const all=filtered('task'),completed=all.filter(t=>Store.done(t,state.date)),active=all.filter(t=>!Store.done(t,state.date)),today=active.filter(t=>Store.matches(t,state.date)),upcoming=active.filter(t=>t.date&&!Store.matches(t,state.date)),any=active.filter(t=>!t.date);return header('Tasks','One task at a time. One brighter day.')+filterToolbar()+[['Today',today],['Upcoming',upcoming],['Anytime',any],['Completed',completed]].map(([name,list])=>`<h3 class="section-label">${name}<small>${list.length}</small></h3><div class="task-list">${list.map(t=>taskRow(t,Store.matches(t,state.date)?state.date:t.date||state.date,true)).join('')||empty(name==='Completed'?'Your finished tasks will bloom here.':'No tasks in this section.')}</div>`).join('')}
function events(){const list=filtered('event');return header('Events','Appointments, plans, and moments to look forward to.')+filterToolbar()+list.map(t=>`<section class="panel" style="padding:16px;margin-bottom:13px">${taskRow(t,t.date,true)}<div style="display:flex;gap:13px;flex-wrap:wrap;margin:13px 5px 0;font-size:12px;color:#bac8a5"><span>${icon('clock-3')} ${time(t.time)}${t.end?' – '+time(t.end):''}</span>${t.location?`<span>${icon('map-pin')} ${esc(t.location)}</span>`:''}<span>${t.repeat==='Never'?'One-time event':esc(t.repeat)}</span><span>${t.synced?'Google Calendar · simulated':'Local event'}</span></div>${t.notes?`<p style="font-size:12px;margin-top:12px;color:#cad4b4">${esc(t.notes)}</p>`:''}</section>`).join('')+(list.length?'':empty('No events match these filters.'))}
function focus(){const f=Store.data.focus,history=f.history||[],todayMinutes=history.filter(x=>x.date===Store.iso()).reduce((sum,x)=>sum+x.minutes,0);let streak=0,date=Store.iso();const days=new Set(history.map(x=>x.date));if(!days.has(date))date=Store.shift(date,-1);while(days.has(date)){streak++;date=Store.shift(date,-1)}return header('Focus','Let the outside world wait a little.')+`<section class="panel ornate focus-page"><h3>Focus Session</h3><div class="focus-large-ring"><div class="timer-value" id="focus-time">${timerText()}</div><small id="focus-status">${state.focusRunning?'A quiet moment in progress':'Find your rhythm'}</small></div><div class="focus-controls"><button class="primary" data-action="focus-start">${icon('play')} ${state.focusRunning?'Running':'Start'}</button><button class="secondary" data-action="focus-pause">${icon('pause')} Pause</button><button class="secondary" data-action="focus-stop">${icon('square')} Stop</button></div><div class="focus-options">${[25,45,60].map(n=>`<button class="secondary" data-action="focus-mode" data-minutes="${n}">${n} min</button>`).join('')}<button class="secondary" data-action="focus-custom">Custom</button></div><div class="focus-inputs"><label>Current task<select id="focus-task"><option value="">Choose a task</option>${Store.data.items.filter(t=>t.kind==='task'&&!t.done).map(t=>`<option value="${t.id}" ${f.task===t.id?'selected':''}>${esc(t.title)}</option>`).join('')}</select></label><label>Session goal<input id="focus-goal" value="${esc(f.goal)}" placeholder="What would you like to accomplish?"></label></div></section><section class="panel focus-stats"><div><strong>${todayMinutes} min</strong>Today Focused</div><div><strong>${f.sessions}</strong>Sessions Completed</div><div><strong>${streak} day${streak===1?'':'s'}</strong>Current Streak</div></section>`}
function timerText(){const n=Math.max(0,state.focusRemaining);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function categories(){return header('Categories','Give every part of your day a place.',`<button class="primary" data-action="add-category">${icon('plus')} Add Category</button>`)+`<div class="category-grid">${Store.data.categories.map(c=>`<section class="panel category-card" draggable="true" data-category="${c.id}">${icon(c.icon)}<div><h4>${esc(c.name)}</h4><small>${Store.data.items.filter(t=>t.category===c.name).length} items</small></div><div class="category-actions"><button data-action="edit-category" data-id="${c.id}" aria-label="Edit ${esc(c.name)}">${icon('pencil')}</button><button data-action="delete-category" data-id="${c.id}" aria-label="Delete ${esc(c.name)}">${icon('trash-2')}</button></div></section>`).join('')}</div><p class="calendar-note">Drag categories to reorder them. Deleting a category moves its items to Other.</p>`}
function reminderRecords(){const records=[];for(let i=0;i<8;i++){const date=Store.shift(Store.today,i);for(const t of Store.on(date)){if(!t.time||Store.done(t,date))continue;for(const m of t.reminders||[]){const due=new Date(date+'T'+t.time);due.setMinutes(due.getMinutes()-m);records.push({t,date,m,due})}}}return records.sort((a,b)=>a.due-b.due)}
function reminders(){const records=reminderRecords();return header('Reminders','Gentle nudges, right when you need them.',`<button class="secondary" data-action="notifications">${icon('bell-ring')} Preview Alert</button>`)+`<div class="notification-banner">Alerts run while this prototype is open. Google and desktop delivery are simulated.</div>`+['Today','Tomorrow','Upcoming'].map((name,i)=>{const list=records.filter(r=>i===0?Store.iso(r.due)===Store.today:i===1?Store.iso(r.due)===Store.shift(Store.today,1):Store.iso(r.due)>Store.shift(Store.today,1));return `<h3 class="section-label">${name}<small>${list.length}</small></h3>${list.map(({t,date,m,due})=>`<section class="panel reminder-card"><div class="rem-time">${time(fromMinutes(due.getHours()*60+due.getMinutes()))}</div>${icon('bell')}<div><h4>${esc(t.title)}</h4><small>${remindText(m)}${i===2?' · '+humanDate(Store.iso(due)):''}${t.snoozeUntil?' · Snoozed until '+new Date(t.snoozeUntil).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'}):''}</small></div><div class="actions"><button data-action="open" data-id="${t.id}" data-date="${date}" aria-label="Edit ${esc(t.title)} reminder">${icon('pencil')}</button><button data-action="snooze" data-id="${t.id}" aria-label="Snooze ${esc(t.title)}">${icon('alarm-clock')}</button><button data-action="delete-reminder" data-id="${t.id}" data-value="${m}" aria-label="Delete reminder for ${esc(t.title)}">${icon('trash-2')}</button><input class="toggle" data-reminder-toggle="${t.id}" type="checkbox" aria-label="Enable ${esc(t.title)} reminders" ${t.reminderEnabled?'checked':''}></div></section>`).join('')||empty('No alerts scheduled here.')}`}).join('')}
function settingSelect(label,key,values){return `<label class="setting-row"><span>${label}</span><select data-setting="${key}" aria-label="${label}">${options(values,Store.data.settings[key])}</select></label>`}
function settingToggle(label,key,description=''){return `<label class="setting-row"><span>${label}${description?`<small>${description}</small>`:''}</span><input class="toggle" type="checkbox" data-setting="${key}" aria-label="${label}" ${Store.data.settings[key]?'checked':''}></label>`}
function settings(){const s=Store.data.settings;return header('Settings','Make this little sanctuary your own.')+`<section class="panel settings-section"><h3>GENERAL</h3>${settingSelect('Start page','start',navs.map(n=>n[0]))}${settingSelect('Time format','time',['12','24'])}${settingSelect('Week starts on','week',['Monday','Sunday'])}</section><section class="panel settings-section"><h3>THEME</h3><div class="setting-row"><span>Enchanted Forest<small>Emerald glass · warm lantern light</small></span><span class="badge">Selected</span></div></section><section class="panel settings-section"><h3>CALENDAR SYNC</h3><div class="notification-banner">Prototype connection only. No Google account is accessed and no real events are sent.</div><div class="setting-row"><span>Google Calendar<small>${s.connected?'johan@example.com · demo account':'Not Connected'}</small></span><button class="secondary" data-action="google-connect">${icon(s.connected?'unlink':'calendar-check')}${s.connected?'Disconnect':'Connect Google Calendar'}</button></div>${s.connected?`<p class="connected-status">${icon('circle-check')} Connected · simulated</p>`:''}${settingSelect('Choose calendar','calendar',['My Tasks','Personal','University','Work'])}${settingSelect('Sync mode','sync',['App → Google Calendar','Two-way sync'])}<label class="setting-row"><span>Default calendar reminder</span><select data-setting="defaultReminder" aria-label="Default calendar reminder">${reminderValues.map(m=>`<option value="${m}" ${s.defaultReminder===m?'selected':''}>${remindText(m)}</option>`).join('')}</select></label>${settingToggle('Sync completed tasks','syncCompleted')}${settingToggle('Delete Google event when local item is deleted','deleteGoogle')}</section><section class="panel settings-section"><h3>NOTIFICATIONS</h3>${settingToggle('Desktop Notifications','desktop','Simulated in-app while open')}${settingToggle('Google Calendar Notifications','googleNotify','Demo preference; requires real integration later')}${settingToggle('Sound','sound')}<div class="setting-row"><span>Reminder preview</span><button class="secondary" data-action="notifications">${icon('bell-ring')} Test notification</button></div></section><section class="panel settings-section"><h3>DATA</h3><p class="settings-description">Your tasks, categories, and preferences stay in this browser on this device. Export a backup to keep a separate copy.</p><div class="btn-row" style="margin-top:14px"><button class="secondary" data-action="export">${icon('download')} Export</button><button class="secondary" data-action="import">${icon('upload')} Import</button><button class="secondary" data-action="export">${icon('archive')} Backup</button><button class="danger" data-action="reset">Reset demo</button><input type="file" id="import-file" accept=".json,application/json" hidden></div></section><section class="panel settings-section"><h3>ABOUT</h3><p class="settings-description">My Tasks · Enchanted Forest<br>Version 1.0 · Interactive desktop prototype<br>No accounts, analytics, or network requests. Data storage: local browser storage. Window controls use browser fullscreen; this is not a packaged Windows executable.</p></section>`}
function openItem(id,date){state.selected=id;if(date)state.date=date;renderEditor();$('#detail').classList.add('open');$('#task-title').focus()}
function newItem(overrides={}){state.selected=null;renderEditor({...blank(),...overrides});$('#detail').classList.add('open');$('#task-title').focus()}
function toast(title,body='',actions=[],stay=false){NotificationService.play();const id='toast-'+uid();$('#toasts').insertAdjacentHTML('beforeend',`<div class="toast" id="${id}"><button class="toast-close" data-action="dismiss-toast" aria-label="Dismiss notification">${icon('x')}</button><div class="toast-title">${icon('leaf')}${esc(title)}</div>${body?`<p>${esc(body)}</p>`:''}${actions.length?`<div class="toast-actions">${actions.map(a=>`<button data-action="${a.action}" ${a.id?`data-id="${a.id}"`:''}>${a.label}</button>`).join('')}</div>`:''}</div>`);refreshIcons();if(!stay)setTimeout(()=>document.getElementById(id)?.remove(),4200)}
function modal(title,content,actions=''){state.modalReturn=document.activeElement;state.modal=title;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-header"><h3>${esc(title)}</h3><button data-action="close-modal" aria-label="Close dialog">${icon('x')}</button></div>${content}${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;refreshIcons();setTimeout(()=>$('.modal input')?.focus()||$('.modal button')?.focus(),25)}
function closeModal(){state.modal=null;$('#modal-root').innerHTML='';state.modalReturn?.focus?.()}
function confirm(title,body,fn){modal(title,`<p>${esc(body)}</p>`,`<button class="secondary" data-action="close-modal">Cancel</button><button class="danger" id="confirm-action">Confirm</button>`);$('#confirm-action').onclick=()=>{closeModal();fn()}}
function contextMenu(id,x,y){$('#context-root').innerHTML=`<div class="context-menu" style="left:${Math.min(x,innerWidth-205)}px;top:${Math.min(y,innerHeight-220)}px" role="menu">${[['open','pencil','Edit details'],['complete','circle-check','Toggle completion'],['duplicate','copy','Duplicate'],['delete','trash-2','Delete item']].map(([a,i,l])=>`<button role="menuitem" data-action="${a}" data-id="${id}">${icon(i)}${l}</button>`).join('')}</div>`;refreshIcons();$('.context-menu button')?.focus()}
function searchModal(){modal('Find a little something',`<input id="global-search" placeholder="Search tasks, events, notes, categories…" aria-label="Search My Tasks"><div class="search-results" id="search-results"></div><div class="modal-footer">Type to search · ↑ ↓ to navigate · Enter to open · Esc to close</div>`);updateSearch('');$('#global-search').oninput=e=>updateSearch(e.target.value)}
function updateSearch(q){const needle=q.trim().toLowerCase(),items=Store.data.items.filter(t=>`${t.title} ${t.notes} ${t.category}`.toLowerCase().includes(needle)).slice(0,8),cats=needle?Store.data.categories.filter(c=>c.name.toLowerCase().includes(needle)):[];$('#search-results').innerHTML=items.map(t=>`<button class="search-result" data-action="search-open" data-id="${t.id}">${icon(category(t.category).icon)}<span>${esc(t.title)}<small>${t.date?humanDate(t.date):'Anytime'} · ${time(t.time)}${t.done?' · Completed':''}</small></span></button>`).join('')+cats.map(c=>`<button class="search-result" data-action="search-category" data-name="${esc(c.name)}">${icon(c.icon)}<span>${esc(c.name)}<small>Category</small></span></button>`).join('')||(empty('No matching items.'));refreshIcons()}
function quickAdd(){modal('Plant a new task',`<p>Try “Gym tomorrow 6pm remind me 30m before”.</p><input id="quick-input" placeholder="What would you like to do?" aria-label="Quick add task"><div id="quick-preview" class="notification-banner">Enter a title, date, and time.</div>`,`<button class="secondary" data-action="close-modal">Cancel</button><button class="primary" id="quick-save">Add Task</button>`);const preview=()=>{const p=parseQuick($('#quick-input').value);$('#quick-preview').textContent=`${p.title||'Task'} · ${humanDate(p.date)} · ${time(p.time)}${p.reminders.length?' · '+remindText(p.reminders[0]):''}`};$('#quick-input').oninput=preview;$('#quick-save').onclick=()=>{const p=parseQuick($('#quick-input').value);if(!p.title){$('#quick-input').focus();return}const t={...blank(),...p,id:uid(),order:Store.data.items.length};Store.data.items.push(t);Store.persist();closeModal();state.selected=t.id;state.date=t.date;render();toast('A new task is planted',t.title)};$('#quick-input').onkeydown=e=>{if(e.key==='Enter')$('#quick-save').click()}}
function parseQuick(s){let title=s.trim(),date=state.date,tm='',rem=[];if(/\btomorrow\b/i.test(title)){date=Store.shift(Store.today,1);title=title.replace(/\btomorrow\b/i,'')}else if(/\btoday\b/i.test(title)){date=Store.today;title=title.replace(/\btoday\b/i,'')}const r=title.match(/(?:remind(?: me)?\s+)(\d+)\s*(m|min|minutes?|h|hours?)\s*(?:before)?/i);if(r){rem=[Number(r[1])*(r[2].toLowerCase().startsWith('h')?60:1)];title=title.replace(r[0],'')}const m=title.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);if(m){const h=Number(m[1])%12+(m[3].toLowerCase()==='pm'?12:0);tm=fromMinutes(h*60+Number(m[2]||0));title=title.replace(m[0],'')}return {title:title.replace(/\s+/g,' ').trim(),date,time:tm,reminders:rem,reminderEnabled:rem.length>0}}
function deleteItem(id){const t=getItem(id);if(!t)return;confirm('Let this task go?',`Delete “${t.title}”${t.repeat!=='Never'?' and its recurring series':''}? This cannot be undone.`,()=>{Store.data.items=Store.data.items.filter(x=>x.id!==id);Store.persist();if(state.selected===id)state.selected=null;render();toast('Item deleted')})}
function categoryModal(id){const c=Store.data.categories.find(c=>c.id===id);modal(c?'Edit Category':'Add Category',`<label>Name<input id="category-name" value="${esc(c?.name||'')}" maxlength="35" placeholder="e.g. Creative time"></label><label>Icon<select id="category-icon">${options(['leaf','book-open','laptop','dumbbell','heart-pulse','moon','calendar-check','users','shopping-bag','sparkles','palette','music','coffee','paw-print'],c?.icon||'leaf')}</select></label>`,`<button class="secondary" data-action="close-modal">Cancel</button><button class="primary" id="category-save">Save Category</button>`);$('#category-save').onclick=()=>{const name=$('#category-name').value.trim(),ic=$('#category-icon').value;if(!name||Store.data.categories.some(x=>x.name.toLowerCase()===name.toLowerCase()&&x.id!==id)){toast('Choose a unique category name');return}if(c){Store.data.items.forEach(t=>{if(t.category===c.name)t.category=name});c.name=name;c.icon=ic}else Store.data.categories.push({id:uid(),name,icon:ic});Store.persist();closeModal();render();toast('Category saved')}}
function notify(id){const t=getItem(id)||Store.data.items.find(t=>!t.done)||Store.data.items[0];if(!t){toast('Nothing to remind you of','Add a task with a reminder first.');return}toast(t.title+' starts soon',`${humanDate(t.date||Store.today)} · ${time(t.time)} · Reminder preview`,[{label:'Done',action:'notification-done',id:t.id},{label:'Snooze 10 min',action:'snooze',id:t.id},{label:'Open',action:'notification-open',id:t.id}],true)}
function exportData(){const data=new Blob([JSON.stringify({version:1,...Store.data},null,2)],{type:'application/json'}),url=URL.createObjectURL(data),a=document.createElement('a');a.href=url;a.download=`my-tasks-backup-${Store.today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported','Keep this file somewhere safe.')}
function importData(file){if(!file)return;if(file.size>5000000){toast('Backup is too large');return}file.text().then(text=>{try{const data=JSON.parse(text);if(!Array.isArray(data.items)||!Array.isArray(data.categories)||!data.settings||data.items.some(t=>typeof t.title!=='string'||typeof t.id!=='string'||!Array.isArray(t.reminders)||t.date&&!/^\d{4}-\d{2}-\d{2}$/.test(t.date)||t.time&&!/^\d{2}:\d{2}$/.test(t.time))||data.categories.some(c=>typeof c.name!=='string'||typeof c.id!=='string'||typeof c.icon!=='string'))throw Error();confirm('Restore this backup?',`Replace your current ${Store.data.items.length} items with ${data.items.length} items from this backup?`,()=>{data.focus??={seconds:1500,mode:25,sessions:0,minutes:0,goal:'One small step forward',task:''};Store.replace(data);state.selected=null;state.focusRemaining=data.focus.seconds;state.focusRunning=false;render();toast('Backup restored')})}catch{toast('This backup could not be read','Choose a My Tasks JSON backup. Your current data is unchanged.')}})}
function startFocus(){if(state.focusRunning)return;if(state.focusRemaining<=0)state.focusRemaining=Store.data.focus.mode*60;state.focusStarted=Date.now();state.focusDeadline=Date.now()+state.focusRemaining*1000;state.focusRunning=true;render()}
function pauseFocus(){if(state.focusRunning){state.focusRemaining=Math.max(0,Math.ceil((state.focusDeadline-Date.now())/1000));state.focusRunning=false;Store.data.focus.seconds=state.focusRemaining;Store.persist();render()}}
const actions={
 'advanced-options':b=>{const on=$('#task-form').classList.toggle('show-options');b.setAttribute('aria-expanded',String(on));b.innerHTML=icon(on?'chevron-up':'chevron-down')+(on?'Fewer task options':'More task options');refreshIcons()},
 search:searchModal,new:()=>newItem(),quick:quickAdd,'close-editor':()=>$('#detail').classList.remove('open'),
 fullscreen:()=>document.fullscreenElement?document.exitFullscreen():$('.app-window').requestFullscreen().catch(()=>toast('Use F11 for fullscreen')),
 complete:(b)=>{Store.toggle(b.dataset.id,b.dataset.date||state.date);render()},
 context:(b,e)=>contextMenu(b.dataset.id,e.clientX,e.clientY),open:b=>openItem(b.dataset.id,b.dataset.date),delete:b=>deleteItem(b.dataset.id),
 duplicate:b=>{const t=getItem(b.dataset.id);if(t){Store.data.items.push({...structuredClone(t),id:uid(),title:t.title+' (copy)',done:false,completedDates:[],order:Store.data.items.length});Store.persist();render();toast('Task duplicated')}},
 'mini-prev':()=>moveMini(-1),'mini-next':()=>moveMini(1),'select-date':b=>{state.date=b.dataset.date;state.miniDate=state.date;state.selected=null;render()},
 'cal-prev':()=>moveCalendar(-1),'cal-next':()=>moveCalendar(1),'cal-today':()=>{state.date=Store.today;render()},
 'focus-start':startFocus,'focus-pause':pauseFocus,'focus-stop':()=>{state.focusRunning=false;state.focusRemaining=Store.data.focus.mode*60;Store.data.focus.seconds=state.focusRemaining;Store.persist();render()},
 'focus-mode':b=>setFocusMode(Number(b.dataset.minutes)),
 'focus-custom':()=>{modal('Your own rhythm','<label>Minutes<input id="custom-minutes" type="number" min="1" max="180" value="30"></label>','<button class="primary" id="custom-save">Set duration</button>');$('#custom-save').onclick=()=>{const n=Number($('#custom-minutes').value);if(n<1||n>180)return;setFocusMode(n);closeModal()}},
 'add-category':()=>categoryModal(),'edit-category':b=>categoryModal(b.dataset.id),
 'delete-category':b=>{const c=Store.data.categories.find(c=>c.id===b.dataset.id);if(c.name==='Other'){toast('Keep Other for uncategorized items');return}confirm('Delete this category?',`Items in ${c.name} will move to Other.`,()=>{if(!Store.data.categories.some(c=>c.name==='Other'))Store.data.categories.push({id:uid(),name:'Other',icon:'sparkles'});Store.data.items.forEach(t=>{if(t.category===c.name)t.category='Other'});Store.data.categories=Store.data.categories.filter(x=>x.id!==c.id);Store.persist();render()})},
 notifications:()=>notify(),snooze:b=>{const t=getItem(b.dataset.id);NotificationService.snooze(t);b.closest('.toast')?.remove();toast('A little breathing room','Reminder snoozed for 10 minutes.');if(state.page==='Reminders')render()},
 'notification-done':b=>{const t=getItem(b.dataset.id);if(!Store.done(t,t.date||Store.today))Store.toggle(t.id,t.date||Store.today);b.closest('.toast')?.remove();render();toast('A little progress made',t.title)},
 'notification-open':b=>{b.closest('.toast')?.remove();openItem(b.dataset.id)},'dismiss-toast':b=>b.closest('.toast').remove(),
 'delete-reminder':b=>confirm('Remove this reminder?','The task will stay in your schedule.',()=>{const t=getItem(b.dataset.id);t.reminders=t.reminders.filter(m=>m!==Number(b.dataset.value));Store.persist();render()}),
 'remove-reminder':b=>{const f=$('#task-form'),values=JSON.parse(f.dataset.reminders).filter(m=>m!==Number(b.dataset.value));f.dataset.reminders=JSON.stringify(values);b.remove()},
 'google-connect':async b=>{if(Store.data.settings.connected){await CalendarService.disconnect();render();toast('Demo disconnected');return}b.disabled=true;b.textContent='Connecting demo…';await CalendarService.connect();render();toast('Google Calendar connected','Simulated connection to johan@example.com. No real account accessed.')},
 'close-modal':closeModal,'search-open':b=>{const id=b.dataset.id;closeModal();openItem(id)},'search-category':b=>{state.filterCategory=b.dataset.name;state.page='Tasks';closeModal();render()},export:exportData,import:()=>$('#import-file').click(),
 reset:()=>confirm('Reset the demo?','This will replace your local items and preferences with the original sample data. Export a backup first if needed.',()=>{Store.reset();state.selected=null;state.focusRemaining=1500;state.focusRunning=false;render();toast('A fresh little start')})
};
function setFocusMode(n){state.focusRunning=false;Store.data.focus.mode=n;state.focusRemaining=n*60;Store.data.focus.seconds=state.focusRemaining;Store.persist();render()}
function moveMini(n){const d=new Date(state.miniDate+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+n);state.miniDate=Store.iso(d);$('#main').innerHTML=home();refreshIcons()}
function moveCalendar(n){if(state.view==='Month'){const d=new Date(state.date+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+n);state.date=Store.iso(d)}else state.date=Store.shift(state.date,n*(state.view==='Week'?7:1));render()}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(b){if(b.type!=='submit')e.preventDefault();actions[b.dataset.action]?.(b,e);if(b.dataset.action!=='context')$('#context-root').innerHTML='';return}
 const p=e.target.closest('[data-page]');if(p){state.page=p.dataset.page;state.selected=null;state.query='';render();$('#main').scrollTop=0;if(state.page==='Calendar')scrollCalendar();return}
 const v=e.target.closest('[data-view]');if(v){state.view=v.dataset.view;render();scrollCalendar();return}
 const item=e.target.closest('[data-item]');if(item){openItem(item.dataset.item,item.dataset.date);return}
 const cell=e.target.closest('[data-slot-date]');if(cell){const rect=cell.getBoundingClientRect(),minute=Math.floor((e.clientY-rect.top)/56*60/15)*15;newItem({date:cell.dataset.slotDate,time:fromMinutes(Number(cell.dataset.hour)*60+minute),end:fromMinutes(Number(cell.dataset.hour)*60+minute+60),kind:'event'});return}
 const month=e.target.closest('[data-month-date]');if(month){state.date=month.dataset.monthDate;state.view='Day';render();scrollCalendar();return}
 if(e.target.classList.contains('modal-backdrop'))closeModal();if(!e.target.closest('.context-menu'))$('#context-root').innerHTML='';
});
document.addEventListener('contextmenu',e=>{const t=e.target.closest('[data-item]');if(t){e.preventDefault();contextMenu(t.dataset.item,e.clientX,e.clientY)}});
document.addEventListener('change',e=>{const el=e.target;
 if(el.dataset.setting){Store.data.settings[el.dataset.setting]=el.type==='checkbox'?el.checked:el.dataset.setting==='defaultReminder'?Number(el.value):el.value;Store.persist();toast('Preference saved');return}
 if(el.dataset.filter){state[el.dataset.filter]=el.value;render();return}
 if(el.dataset.reminderToggle){getItem(el.dataset.reminderToggle).reminderEnabled=el.checked;Store.persist();return}
 if(el.id==='import-file'){importData(el.files[0]);el.value='';return}
 if(el.id==='focus-task'||el.id==='focus-goal'){Store.data.focus[el.id==='focus-task'?'task':'goal']=el.value;Store.persist()}
 if(el.name==='reminderEnabled')$('#reminder-options').hidden=!el.checked;
 if(el.name==='repeat')$('#interval-field').hidden=el.value!=='Custom';
 if(el.name==='kind')$('#location-field').hidden=el.value!=='event';
 if(el.id==='reminder-add'&&el.value!==''){const f=$('#task-form'),vals=JSON.parse(f.dataset.reminders),n=Number(el.value);if(!vals.includes(n)){vals.push(n);f.dataset.reminders=JSON.stringify(vals);el.insertAdjacentHTML('beforebegin',`<button type="button" class="reminder-chip" data-action="remove-reminder" data-value="${n}">${remindText(n)} ×</button>`)}el.value=''}
});
document.addEventListener('input',e=>{if(e.target.id==='task-query'){state.query=e.target.value;const pos=e.target.selectionStart;$('#main').innerHTML=state.page==='Events'?events():tasks();refreshIcons();$('#task-query').focus();$('#task-query').setSelectionRange(pos,pos)}if(e.target.id==='focus-goal'){Store.data.focus.goal=e.target.value;Store.persist()}});
document.addEventListener('submit',e=>{if(e.target.id!=='task-form')return;e.preventDefault();const f=e.target,fd=new FormData(f),prev=getItem(state.selected);const t={...prev,...blank(),id:prev?.id||uid(),order:prev?.order??Store.data.items.length};for(const key of ['title','date','time','end','category','kind','repeat','priority','notes','location'])t[key]=String(fd.get(key)||'').trim();t.interval=Math.max(1,Math.min(365,Number(fd.get('interval'))||2));t.reminders=JSON.parse(f.dataset.reminders);t.reminderEnabled=fd.has('reminderEnabled');t.synced=fd.has('synced');t.done=fd.has('done');t.completedDates=prev?.completedDates||[];if(!t.title)return;if(t.end&&(!t.time||t.end<=t.time)){toast('Check the event time','End time must be after start time on the same day.');return}if(t.repeat!=='Never'&&!t.date){toast('Choose a date for this repeating item');return}if(prev?.repeat!=='Never'&&prev?.id&&t.repeat!=='Never'){t.completedDates=t.done?[...new Set([...t.completedDates,state.date])]:t.completedDates.filter(d=>d!==state.date)}if(t.synced)t.syncResult=CalendarService.sync(t);if(prev)Store.data.items[Store.data.items.findIndex(x=>x.id===t.id)]=t;else Store.data.items.push(t);const ok=Store.persist();state.selected=t.id;if(t.date)state.date=t.date;render();toast(prev?'Changes saved':'A new task is planted',t.synced?(Store.data.settings.connected?'Google Calendar sync simulated.':'Local item saved. Connect the demo in Settings to simulate sync.'):t.title);if(!ok)toast('Storage is unavailable','Export a backup before closing this window.')});
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal();return}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();quickAdd();return}
 if(e.key==='Escape'){if(state.modal)closeModal();$('#context-root').innerHTML='';$('#detail').classList.remove('open');return}
 if(state.modal&&e.key==='Tab'){const list=$$('.modal button,.modal input,.modal select,.modal textarea').filter(x=>!x.disabled),first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
 if(state.modal&&e.key==='ArrowDown'&&$('#search-results')){e.preventDefault();const results=$$('.search-result'),i=results.indexOf(document.activeElement);results[Math.min(i+1,results.length-1)]?.focus()}
 if(state.modal&&e.key==='ArrowUp'&&$('#search-results')){e.preventDefault();const results=$$('.search-result'),i=results.indexOf(document.activeElement);if(i<=0)$('#global-search').focus();else results[i-1]?.focus()}
 if(e.key==='Enter'&&!e.target.matches('input,textarea,select,button')){const t=e.target.closest('[data-item]');if(t){e.preventDefault();openItem(t.dataset.item,t.dataset.date)}const s=e.target.closest('[data-slot-date]');if(s){e.preventDefault();newItem({date:s.dataset.slotDate,time:fromMinutes(Number(s.dataset.hour)*60),kind:'event'})}const m=e.target.closest('[data-month-date]');if(m){state.date=m.dataset.monthDate;state.view='Day';render();scrollCalendar()}}
});
document.addEventListener('dragstart',e=>{if(e.target.closest('.resize-handle')){e.preventDefault();return}const item=e.target.closest('[data-item]'),cat=e.target.closest('[data-category]');if(item){state.drag={type:'item',id:item.dataset.item};e.dataTransfer.setData('text/plain',item.dataset.item)}else if(cat){state.drag={type:'category',id:cat.dataset.category};e.dataTransfer.setData('text/plain',cat.dataset.category)}});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-slot-date],[data-item],[data-category]'))e.preventDefault()});
document.addEventListener('drop',e=>{e.preventDefault();const drag=state.drag;if(!drag)return;const slot=e.target.closest('[data-slot-date]'),target=e.target.closest('[data-item]'),cat=e.target.closest('[data-category]');if(drag.type==='item'){const t=getItem(drag.id);if(slot){const duration=t.end&&t.time?minutes(t.end)-minutes(t.time):60;t.date=slot.dataset.slotDate;t.time=fromMinutes(Number(slot.dataset.hour)*60);t.end=fromMinutes(minutes(t.time)+duration);Store.persist();render();scrollCalendar();toast('Time updated',`${t.title} · ${time(t.time)}`)}else if(target&&target.dataset.item!==drag.id){const list=Store.data.items.sort((a,b)=>a.order-b.order),from=list.findIndex(t=>t.id===drag.id),to=list.findIndex(t=>t.id===target.dataset.item);list.splice(to,0,...list.splice(from,1));list.forEach((t,i)=>t.order=i);Store.persist();render()}}else if(cat){const cats=Store.data.categories,from=cats.findIndex(c=>c.id===drag.id),to=cats.findIndex(c=>c.id===cat.dataset.category);cats.splice(to,0,...cats.splice(from,1));Store.persist();render()}state.drag=null});
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-resize]');if(!h)return;e.preventDefault();e.stopPropagation();const t=getItem(h.dataset.resize),card=h.closest('.calendar-event'),startY=e.clientY,initial=t.end?minutes(t.end)-minutes(t.time):60;let duration=initial;const move=ev=>{duration=Math.max(15,Math.round((initial+(ev.clientY-startY)/56*60)/15)*15);card.style.height=(duration/60*56-4)+'px'};const up=()=>{t.end=fromMinutes(minutes(t.time)+duration);Store.persist();document.removeEventListener('pointermove',move);document.removeEventListener('pointerup',up);const sc=$('.calendar-wrap')?.scrollTop;render();if($('.calendar-wrap'))$('.calendar-wrap').scrollTop=sc;toast('Duration updated')};document.addEventListener('pointermove',move);document.addEventListener('pointerup',up,{once:true})});
function scrollCalendar(){setTimeout(()=>{const el=$('.calendar-wrap');if(el&&state.view!=='Month')el.scrollTop=56*8},30)}
const notified=new Set();setInterval(()=>{if(state.focusRunning){state.focusRemaining=Math.max(0,Math.ceil((state.focusDeadline-Date.now())/1000));if($('#focus-time'))$('#focus-time').textContent=timerText();if(state.focusRemaining===0){state.focusRunning=false;Store.data.focus.sessions++;Store.data.focus.minutes+=Store.data.focus.mode;Store.data.focus.history??=[];Store.data.focus.history.push({date:Store.iso(),minutes:Store.data.focus.mode});Store.data.focus.seconds=Store.data.focus.mode*60;Store.persist();toast('A quiet moment, well spent','Focus session complete. Take a little break.',[],true);if(state.page==='Focus')render()}}for(const t of Store.data.items){if(t.snoozeUntil&&Date.now()>=t.snoozeUntil){delete t.snoozeUntil;Store.persist();notify(t.id)}if(Store.data.settings.desktop&&t.reminderEnabled&&!Store.done(t,Store.today)){for(const date of [Store.today,Store.shift(Store.today,1)]){if(!Store.matches(t,date))continue;for(const m of t.reminders){const key=t.id+date+m,due=new Date(date+'T'+t.time).getTime()-m*60000;if(!notified.has(key)&&Date.now()>=due&&Date.now()<due+60000&&!t.snoozeUntil){notified.add(key);notify(t.id)}}}}}},1000);
render();
